# output 列表
patch_list = items_json[0].get("output", [])

if not final_output:
    return items

# 拆分表格行
lines = final_output.split("\n")
new_lines = []

# 1️⃣ 给表头添加 patch 合入情况列
for idx, line in enumerate(lines):
    if idx == 0:
        line = line.rstrip() + "  patch合入情况 |"
    elif idx == 1:
        line = line.rstrip() + "  --- |"
    new_lines.append(line)

# 2️⃣ 处理数据行
updated_lines = new_lines[:2]  # 表头和分隔符
data_lines = new_lines[2:]

# 先把 output 中每个 patch 的 JIRA 对应起来
patch_dict = {}
jira_pattern = re.compile(r'\b[A-Z]+-\d+\b')

for patch in patch_list:
    jiras = jira_pattern.findall(patch)
    for jira in jiras:
        if jira in patch_dict:
            # 同一个 JIRA 多个 patch 内容合并
            patch_dict[jira].append(patch)
        else:
            patch_dict[jira] = [patch]

# 3️⃣ 遍历每一行数据，根据条目列识别 JIRA
for i,line in enumerate(data_lines):
    cols = [c.strip() for c in line.split("|")]

    if len(cols) < 2:
        updated_lines.append(line)
        continue

    jira_match = jira_pattern.search(cols[1])
    if jira_match:
        jira = jira_match.group(0)
        # 如果 patch_dict 中有对应 JIRA，就合并内容
        if jira in patch_dict and i != 0:
            combined_patch = "<br>".join(patch_dict[jira])
            cols[-1] = combined_patch
        else:
            cols[-1] = "—"
    else:
        cols[-1] = "—"

    updated_line = " | ".join(cols)
    updated_lines.append(updated_line)

# 拼回表格
final_output_with_patch = "\n".join(updated_lines)

# 返回 n8n 输出
return [
    {
        "json": {
            "final_output": final_output_with_patch
        }
    }
